// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

contract InvMutTest is Test {
    Size c;

    function setUp() public {
        c = new Size();
    }

    function testFuzz_property(uint256 x) public {
        // Keep the fuzzed input wide; it doesn't matter for this property.
        // The overall rule: for any freshly deployed and unpaused C, paused() must return false.
        // The bug: the returned flag is negated, so paused() returns true for an unpaused contract.
        bool pausedResult = c.paused();
        assertTrue(!pausedResult);
    }
}
